head.script:
// 테스트 설명, 유효성 값 설정
//  - 분리 샘플(_6) : @propval true 의 하위절 "Header Column 만 병합된 경우 각 Column 의 가상 경계 영역에서 Drag 가 가능"
//    중 'Header 가 멀티라인이고 1줄만 병합된 경우' 를 담당(분리 사유).
//    _2 는 Header 1행(멀티라인 아님) 구성으로 가상 경계 Drag 가 가능한 쪽만 검증하므로, 멀티라인 구성은 본 샘플에서 검증한다.
//  - description 은 _1 과 동일 고정, validation 은 멀티라인 구성에서의 가상 경계 동작 2건만
scwin.tData = {
    "description" : "[gridView > P > resize]<br/>마우스 Drag 에 의한 Column 의 너비(Width) 변경을 허용할지 설정합니다.",
    "validation" : [
        "true(기본값) 설정 시, Header 가 멀티라인이고 1줄만 병합된 경우 병합된 줄의 가상 경계에서는 Drag 로 Column 의 너비를 변경할 수 없습니다.",
        "true(기본값) 설정 시, Header 가 멀티라인이면 나머지 줄의 가상 경계에서 Drag 하여 Column 의 너비를 변경할 수 있습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_resize(gdl_boolean) : 미설정('') / true / false. resize 는 @dynamic N 이라 con 변경은 Target 재생성으로 반영.
//    · 미설정('') : resize 속성 자체 미설정 = 엔진 기본값(true)
//    · true       : resize="true"
//    · false      : resize="false" → 어느 경계에서도 Drag 로 너비 변경 불가
//  - 구성 : Header 는 멀티라인(2행) 이고 1줄만 병합.
//           row1 = 그룹A(colSpan=2, col1/col2 병합) + col3(rowSpan=2) + col4(rowSpan=2)
//           row2 = col1 / col2 (병합되지 않은 나머지 줄)
//           · 그룹A 내부의 col1|col2 지점 = '병합된 줄의 가상 경계'
//           · row2 의 col1|col2 지점     = '나머지 줄의 가상 경계'(실제 Header Column 경계)
//           멀티라인 구성에서는 나머지 줄의 가상 경계로 사이즈 조정이 되므로 병합된 줄의 가상 경계선은 리사이즈되지 않는다.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // resize 옵션 (gdl_boolean → getText 로 '' / true / false 라벨 사용)
    let resize = con_resize.getText();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] resize=(현재 [' + (resize === '' ? '미설정' : resize) + ']). Header 는 멀티라인(2행) 이고 1줄만 병합. row1=그룹A(col1+col2 병합)+col3/col4(rowSpan=2), row2=col1 / col2. con 변경은 Target 재생성 버튼으로 반영.\n[절차] 병합된 줄(그룹A) 내부의 col1|col2 가상 경계를 좌우로 Drag → 너비 변화 확인. 이어서 나머지 줄(row2)의 col1|col2 경계를 좌우로 Drag → 너비 변화 확인.\n[확인] [컬럼 너비 확인] 버튼으로 Drag 전후 너비를 비교. 병합된 줄의 가상 경계는 너비 불변, 나머지 줄의 가상 경계는 너비 변경. resize=false 면 어느 경계에서도 너비 불변."', '', 'label1');

    // GridView 와 바인딩할 DataList (4 Column, 4 Row)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "A1", "col2": "B1", "col3": "C1", "col4": "D1" },
        { "col1": "A2", "col2": "B2", "col3": "C2", "col4": "D2" },
        { "col1": "A3", "col2": "B3", "col3": "C3", "col4": "D3" },
        { "col1": "A4", "col2": "B4", "col3": "C4", "col4": "D4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // con 값이 있으면 resize 속성 부여, 미설정이면 속성 자체 미부여(엔진 기본값 true)
    let strAttr = '';
    if (resize !== '') {
        strAttr += ' resize="' + resize + '"';
    }

    // target 그리드 : Header 멀티라인(2행), row1 의 그룹A 만 colSpan=2 로 병합(Header 만 병합)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + strAttr + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:520px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="resize 멀티라인 병합헤더 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column colSpan="2" width="200" style="" inputType="text" id="hcol_group" value="그룹A (col1+col2)"></w2:column>';
    strTarget += '<w2:column rowSpan="2" width="120" style="" inputType="text" id="hcol3" value="col3(H)"></w2:column>';
    strTarget += '<w2:column rowSpan="2" width="120" style="" inputType="text" id="hcol4" value="col4(H)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2(H)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
};



// [컬럼 너비 확인] : 현재 각 Body Column 의 너비 출력
//  - 병합된 줄(그룹A) 가상 경계 / 나머지 줄(row2) 경계 Drag 전후로 클릭하여 너비 변화를 관찰
//  - checkAllType=false, RowNum/RowStatus 미표시 → getColumnWidth 인덱스 : 0=col1, 1=col2, 2=col3, 3=col4
scwin.btn_checkWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====현재 컬럼 너비 (resize=[" + (con_resize.getText() === '' ? '미설정' : con_resize.getText()) + "] / Header 멀티라인)=====");
    bottom.setReturnValue("col1(0) [병합줄 가상경계 좌/나머지줄 col1] : " + target1.getColumnWidth(0));
    bottom.setReturnValue("col2(1) [병합줄 가상경계 우/나머지줄 col2] : " + target1.getColumnWidth(1));
    bottom.setReturnValue("col3(2) : " + target1.getColumnWidth(2));
    bottom.setReturnValue("col4(3) : " + target1.getColumnWidth(3));
};
